import{_ as e,o,c,Q as a}from"./chunks/framework.d7c6e0b6.js";const b=JSON.parse('{"title":"Es6 模块","description":"","frontmatter":{},"headers":[],"relativePath":"mianshi/JavaScript/Es6模块.md","filePath":"mianshi/JavaScript/Es6模块.md","lastUpdated":1750926525000}'),d={name:"mianshi/JavaScript/Es6模块.md"},t=a('<h1 id="es6-模块" tabindex="-1">Es6 模块 <a class="header-anchor" href="#es6-模块" aria-label="Permalink to &quot;Es6 模块&quot;">​</a></h1><h2 id="es5、es6和es2015有什么区别" tabindex="-1">ES5、ES6和ES2015有什么区别? <a class="header-anchor" href="#es5、es6和es2015有什么区别" aria-label="Permalink to &quot;ES5、ES6和ES2015有什么区别?&quot;">​</a></h2><p><code>ES2015</code>特指在<code>2015</code>年发布的新一代<code>JS</code>语言标准，<code>ES6</code>泛指下一代<code>JS</code>语言标准，包含<code>ES2015</code>、<code>ES2016</code>、<code>ES2017</code>、<code>ES2018</code>等。现阶段在绝大部分场景下，<code>ES2015</code>默认等同<code>ES6</code>。<code>ES5</code>泛指上一代语言标准。<code>ES2015</code>可以理解为<code>ES5</code>和<code>ES6</code>的时间分界线</p><h2 id="babel是什么-有什么作用" tabindex="-1">babel是什么，有什么作用? <a class="header-anchor" href="#babel是什么-有什么作用" aria-label="Permalink to &quot;babel是什么，有什么作用?&quot;">​</a></h2><blockquote><p><code>babel</code>是一个 <code>ES6</code> 转码器，可以将 <code>ES6</code> 代码转为 <code>ES5</code> 代码，以便兼容那些还没支持<code>ES6</code>的平台</p></blockquote><h2 id="let有什么用-有了var为什么还要用let" tabindex="-1">let有什么用，有了var为什么还要用let？ <a class="header-anchor" href="#let有什么用-有了var为什么还要用let" aria-label="Permalink to &quot;let有什么用，有了var为什么还要用let？&quot;">​</a></h2><blockquote><p>在<code>ES6</code>之前，声明变量只能用<code>var</code>，<code>var</code>方式声明变量其实是很不合理的，准确的说，是因为<code>ES5</code>里面没有块级作用域是很不合理的。没有块级作用域回来带很多难以理解的问题，比如<code>for</code>循环<code>var</code>变量泄露，变量覆盖等问题。<code>let</code>声明的变量拥有自己的块级作用域，且修复了<code>var</code>声明变量带来的变量提升问题。</p></blockquote>',7),r=[t];function s(l,i,S,n,E,h){return o(),c("div",null,r)}const p=e(d,[["render",s]]);export{b as __pageData,p as default};
